private byte[] encodeAcknowledgements(Map<String, DurableCursor> acknowledgements) {
    ObjectNode root = mapper.createObjectNode();
    acknowledgements.forEach((deviceId, cursor) -> {
        ObjectNode node = root.putObject(deviceId);
        node.put("eventSeq", cursor.eventSeq());
        node.put("snapshotRevision", cursor.snapshotRevision());
    });
    return write(root, "durable acknowledgements");
}

private Map<String, DurableCursor> decodeAcknowledgements(byte[] value) {
    JsonNode root = read(value, "durable acknowledgements");
    if (!root.isObject()) throw corrupt("durable acknowledgements");
    var result = new LinkedHashMap<String, DurableCursor>();
    for (Map.Entry<String, JsonNode> entry : root.properties()) {
        result.put(entry.getKey(), new DurableCursor(
                requiredLong(entry.getValue(), "eventSeq"),
                requiredLong(entry.getValue(), "snapshotRevision")));
    }
    return Map.copyOf(result);
}

